const labels={INFO:'Info',WARNING:'Warnung',FIRE:'Feueralarm',INTRUSION:'Einbruchalarm'};
// Old snapshots and standalone cards may not yet contain the registry.
function alarmTypes(data){return {...Object.fromEntries(Object.entries(labels).map(([id,name])=>[id,{id,name,mode:['INFO','WARNING'].includes(id)?'message':'alarm',priority:id==='INTRUSION'?10:id==='FIRE'?20:id==='WARNING'?90:100,push:true,sound:!['INFO','WARNING'].includes(id),speech:!['INFO','WARNING'].includes(id),popup:!['INFO','WARNING'].includes(id),tone_seconds:null,speech_seconds:null,speech_template:'Achtung. {name}. Standort {site}. {areas}.',channel:name,builtin:true}])),...(data?.alarm_types||{})};}
const alarmLabel=(data,type)=>alarmTypes(data)[type]?.name||type;
const isAlarm=(data,type)=>alarmTypes(data)[type]?.mode==='alarm';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const humanName=(v,uid)=>typeof v==='string'&&v.trim()&&v!==uid&&v!=='Name nicht verfügbar'&&!/^(?:[a-f0-9]{32}|[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12})$/i.test(v.trim())?v.trim():'';
const when=v=>v?new Date(v).toLocaleString('de-DE'):'';
