   if(!device||!this.outputTestDevices(dialog.kind).some(d=>d.id===device.id)||!this.outputEnabled(device,profile,output))throw Error('Diese Ausgabe ist für das gewählte Gerät nicht eingeschaltet oder eingerichtet.');
