 completedTests(){const d=this.data.devices[this.wizard?.draft.id];if(!d?.test_session)return [];return [...new Set(Object.values(this.data.incidents||{}).filter(i=>i.test_device===d.id&&i.test_session===d.test_session&&['ended','false_alarm'].includes(i.status)).map(i=>i.type))];}
 updateTestConfirmation(){const device=this.data.devices[this.wizard?.draft?.id],setupReady=!!device&&!device.setup_pending?.length&&!device.setup_running&&!device.setup_restore_pending&&!device.restore_pending;for(const b of this.shadowRoot.querySelectorAll('[data-test-type]'))b.disabled=!setupReady;const setupStatus=this.shadowRoot.querySelector('#setup-progress');if(setupStatus)setupStatus.textContent=setupReady?'Einrichtung abgeschlossen. Du kannst die Alarmtests starten.':'Einrichtung läuft noch. Handy geöffnet lassen. '+(device?.setup_error||'');const root=this.shadowRoot,done=this.completedTests(),ready=setupReady&&done.includes('FIRE')&&done.includes('INTRUSION'),check=root.querySelector('#tested-check'),button=root.querySelector('#confirm-device');if(check){check.disabled=!ready;if(!ready)check.checked=false;}if(button)button.disabled=!ready||!check?.checked;const status=root.querySelector('#test-progress');if(status)status.textContent=['FIRE','INTRUSION'].map(t=>this.typeLabel(t)+': '+(done.includes(t)?'geprüft':'noch prüfen')).join(' · ');}
