 sensors(kind){return Object.keys(this.hass.states).filter(id=>id.startsWith('sensor.')&&(kind==='ringer'?/ringer.?mode/.test(id):/notification/.test(id)&&/volume/.test(id))&&this.hass.states[id].attributes?.unit_of_measurement!=='%');}
 chooseSensor(kind,current){const ids=this.sensors(kind);if(current&&!ids.includes(current))ids.push(current);return `<option value="">Bitte auswählen</option>${ids.map(id=>this.option(id,this.sensorName(id),current)).join('')}`;}
 browserChoices(){if(this.data.browser_connections?.length)return this.data.browser_connections;return Object.entries(this.hass.states).filter(([id,s])=>id.startsWith('sensor.')&&/browser_id$/.test(id)&&s.state&&!['unknown','unavailable'].includes(s.state)).map(([entity,s])=>{const v=entity.replace(/browser_id$/,'browser_visibility');return {id:s.state,visibility_sensor:this.hass.states[v]?v:''};});}
