// HA can replace its element registry after extra_module_url has executed.
// Repair definitions against the final registry rather than relying on cache timing.
function registerAlarmElements(){
 for(const [name,ctor] of [['alarm-system-card',AlarmCard],['alarm-system-panel',AlarmPanel]])
  if(!window.customElements.get(name))window.customElements.define(name,ctor);
}
registerAlarmElements();
const registryAtLoad=window.customElements;
const registryCheck=setInterval(()=>{
 if(window.customElements!==registryAtLoad||window.customElements.get('home-assistant')){
  registerAlarmElements();
  if(window.customElements.get('home-assistant'))clearInterval(registryCheck);
 }
},100);
window.addEventListener('pagehide',()=>clearInterval(registryCheck),{once:true});
